@startuml

class Employee {
  + identifyingNumber : string
  + name : string
  + address : string
}

class AssemblyService {
  + kilometers : int
  + workHours : float
  + admissionDate : date
  + finishDate : date
}

class PartOrAccessory {
  + category : string
  + serialNumber : string
  + price : double
}

class Car {
  + licensePlate : string
  + make : string
  + model : string
  + color : string
}

class Owner {
  + name : string
  + identifyingNumber : string
  + address : string
  + phone : string
}

Owner "1" -- "*" Car : owns

Car "1" -- "*" AssemblyService : undergoes
AssemblyService "*" -- "1" Employee : is executed by
AssemblyService "*" -- "*" PartOrAccessory : fits

PartOrAccessory "*" -- "*" Car : fits in models

@enduml

